function findTargetSumWays(nums, target) {
  const memo = new Map();                        // "i,sum" -> ways
  const count = (i, sum) => {
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i + "," + sum;
    if (!memo.has(key)) memo.set(key, count(i + 1, sum + nums[i]) + count(i + 1, sum - nums[i]));
    return memo.get(key);
  };
  return count(0, 0);
}

